package tools

// toolDescriptionsEN provides English localizations for all built-in AI tool definitions.
var toolDescriptionsEN = map[string]string{
	"list_databases":          "Returns the list of databases (MySQL, MariaDB, PostgreSQL) and their sizes on the server.",
	"inspect_databases":       "Returns status of active database engines on the server, listening ports, and versions.",
	"prepare_config_diff":     "Prepares a plan for modifying configuration files (Nginx, Apache, PHP, MySQL) with Diff computation. Requires user confirmation.",
	"propose_service_restart": "Creates a request to restart a system service (nginx, apache2, php-fpm, mysql). Requires user confirmation.",
	"read_webserver_logs":     "Reads recent log entries from web servers (Nginx error.log/access.log, Apache error.log/access.log, PHP-FPM logs, or specific site logs). Safe read-only operation.",
	"get_service_status":      "Returns detailed system service status (systemctl status <service>): active state, exit code, PID, resource usage, and recent journal lines. Safe read-only operation.",
	"get_service_logs":        "Reads system service journal logs via journalctl (journalctl -u <service> -n <lines>). Helps inspect startup failures, crashes, and unit errors. Safe read-only operation.",
	"check_web_topology":      "Instantly detects server web stack architecture: Nginx-only, Apache-only, or Hybrid (Nginx frontend + Apache backend), open ports, and PHP runtime mode (Apache mod_php or isolated PHP-FPM unix sockets in /run/php/*.sock). Safe read-only operation.",
	"inspect_php_environment": "Inspects server PHP environment: installed CLI versions, active PHP-FPM pools, sockets in /run/php/, and loaded modules. Safe read-only operation.",
	"read_config_file":        "Safely reads configuration file contents on the server (/etc/nginx/, /etc/apache2/, /etc/php/). Symlinks are resolved server-side, reading private keys and credentials is prohibited. Safe read-only operation.",
	"get_listening_ports":     "Returns all listening network ports (TCP/UDP) and their binding processes (ss -tulpn). Helps determine active services and port conflicts (80, 443, 8080, 3306, etc.). Safe read-only operation.",
	"test_webserver_syntax":   "Tests web server configuration file syntax (nginx -t or apachectl configtest / httpd -t) without applying changes. Safe read-only operation.",
	"get_firewall_status":     "Returns system firewall status (UFW or Firewalld) and list of allowed ports and rules.",
	"get_fail2ban_status":     "Returns status of Fail2ban brute-force protection service, active jails, and banned IP addresses.",
	"run_security_audit":      "Runs a comprehensive server security audit: checks SSH (root access, password auth, ports), firewall (UFW), Fail2ban, exposed database ports, and brute-force attempts.",
	"get_server_status":       "Returns server details, connection status, OS, and diagnostic metrics.",
	"get_system_metrics":      "Returns real-time server CPU load, RAM usage, and disk utilization metrics.",
	"list_sites":              "Returns the list of hosted sites and virtual hosts on the server (domains, document roots, PHP versions, SSL).",
	"get_vhost_config":        "Reads VirtualHost configuration file content (Nginx or Apache) for inspection and syntax error detection.",
	"diagnose_site_outage":    "Performs end-to-end automated site outage diagnosis: checks DNS, HTTP/HTTPS response, SSL certs, web servers (Nginx/Apache), PHP-FPM sockets, and error logs.",
	"optimize_server_configs": "Analyzes server RAM and CPU cores, computes optimal tuning parameters for MySQL/MariaDB (InnoDB Buffer Pool), PHP-FPM (pm.max_children), and Nginx (worker_processes/gzip), providing actionable recommendations.",
	"inspect_docker_containers": "Returns Docker daemon status, versions of Docker and Compose, and lists all containers (running and stopped), images, and Compose projects on the server.",
	"get_docker_container_logs": "Reads recent log entries from a specific Docker container by name or ID. Safe read-only operation.",
	"inspect_ssl_certificates":  "Returns information about installed SSL/TLS certificates and Certbot/Let's Encrypt configuration on the server (domains, expiration dates, days remaining, renewal status).",
	"list_cron_jobs":            "Returns scheduled cron jobs (crontab) on the server for a specific user or all users (including /etc/crontab and /etc/cron.d).",
	"check_package_updates":     "Simulates OS package updates (APT/DNF) without modifying the system, reporting available upgrades, security advisories, and reboot requirements.",
	"analyze_disk_usage":        "Analyzes server disk utilization: partition mount points, largest directories and files in the specified path, and recommended cleanup opportunities.",
	"list_system_processes":     "Returns top running processes on the server sorted by CPU and memory usage (PID, user, % CPU, % RAM, command). Helps identify resource-heavy or hung tasks.",
	"list_backups":              "Returns the list of server backup records from the TameStack database.",
	"inspect_site_app":          "Inspects a site's web application: detects framework (Laravel, WordPress, Node.js, Python, Go), PHP version, .env presence, queue worker and scheduler status.",
	"get_app_process_status":    "Returns systemd process status for a site app (Node.js / Python / Go): unit name, active state, PID, memory, ExecStart, and recent logs.",
	"list_system_users":         "Returns Linux and SFTP users on the server: UID/GID, home directories, shells, and SFTP Chroot isolation status.",
	"list_user_ssh_keys":        "Returns authorized public SSH keys (authorized_keys) for the specified Linux user on the server. Safe read-only operation (public keys only).",
	"inspect_mail_server":       "Inspects the mail stack (Postfix, Dovecot, OpenDKIM): service status, mail domains, SPF/DMARC/DKIM DNS records, mailboxes, and forwarding aliases.",
	"inspect_dns_zones":         "Returns BIND9 DNS server status and list of local DNS zones; if domain is provided, also returns zone resource records (A, AAAA, MX, TXT, CNAME, NS).",
}
